body:
Hi,

I am trying to work out my routing and it seems like when I setState my searchState inside onSearchStateChange, my components goes into infinite loop.

Here is my code.

```jsx
class Filter extends React.Component {

  constructor() {
    super();
    this.state = {
      searchState: {...qs.parse(document.location.search.slice(1)) }
    };
  }

  onSearchStateChange(nextState) {
    // the next line causes my component to render again and again. 
    this.setState({ searchState: nextState });
    window.history.replaceState({}, "", `?${qs.stringify(nextState)}`);
  }
  createURL(state) {
    return `?${qs.stringify(state)}`;
  }




  render() {
    console.log("rendering");
    const {
      category_slug = "",
      brand_slug = ""
    } = this.props.params;

    return (
      <InstantSearch
        appId={ALGOLIA_APPID}
        apiKey={ALGOLIA_APIKEY}
        indexName={MAININDEX}
        searchState={this.state.searchState}
        onSearchStateChange={this.onSearchStateChange.bind(this)}>

        <div>
        {/* Some Refinements */}
        </div>
      </InstantSearch>
    );
  }
}
```
